diff --git a/runtime/orchestrator/tests/task-branch-state.test.ts b/runtime/orchestrator/tests/task-branch-state.test.ts
new file mode 100644
index 0000000..46527fc
--- /dev/null
+++ b/runtime/orchestrator/tests/task-branch-state.test.ts
@@ -0,0 +1,126 @@
+/**
+ * Unit tests for task-branch-state.ts
+ *
+ * Covers:
+ *   1. deleteLocalBranchIfOrphan — no local branch (returns false, no delete call)
+ *   2. deleteLocalBranchIfOrphan — local branch found, delete succeeds (returns true)
+ *   3. deleteLocalBranchIfOrphan — local branch found, delete fails (returns false)
+ *   4. tryReadTaskFromBranch — reads YAML from origin/<branch>
+ *   5. tryReadTaskFromBranch — returns null on non-zero exit
+ *   6. tryReadTaskFromBranch — returns null on empty stdout
+ *   7. tryReadTaskFromBranch — returns null on invalid YAML
+ */
+
+import { describe, it, expect, vi, afterEach } from "vitest";
+import { spawnSync } from "child_process";
+import { deleteLocalBranchIfOrphan, tryReadTaskFromBranch } from "../src/task-branch-state.js";
+
+vi.mock("child_process", async (importOriginal) => {
+  const actual = await importOriginal<typeof import("child_process")>();
+  return { ...actual, spawnSync: vi.fn() };
+});
+
+const ROOT = "/workspace/root";
+const BRANCH = "feature/my-feature-T1";
+const REL_PATH = "docs/features/my-feature/tasks/T1.yaml";
+
+function mockSpawnResult(stdout: string, status: number): ReturnType<typeof spawnSync> {
+  return {
+    pid: 0, output: [], stdout, stderr: "", status, signal: null, error: undefined,
+  } as unknown as ReturnType<typeof spawnSync>;
+}
+
+afterEach(() => {
+  vi.clearAllMocks();
+});
+
+// ── deleteLocalBranchIfOrphan ─────────────────────────────────────────────────
+
+describe("deleteLocalBranchIfOrphan", () => {
+  it("returns false and skips delete when no local branch exists", () => {
+    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnResult("", 0)); // branch --list → empty
+
+    const result = deleteLocalBranchIfOrphan(ROOT, BRANCH);
+
+    expect(result).toBe(false);
+    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(1);
+    const [cmd, args] = vi.mocked(spawnSync).mock.calls[0];
+    expect(cmd).toBe("git");
+    expect(args).toContain("branch");
+    expect(args).toContain("--list");
+    expect(args).toContain(BRANCH);
+  });
+
+  it("returns true when local branch exists and delete succeeds", () => {
+    vi.mocked(spawnSync)
+      .mockReturnValueOnce(mockSpawnResult(`  ${BRANCH}\n`, 0)) // branch --list → found
+      .mockReturnValueOnce(mockSpawnResult("", 0));              // branch -D → success
+
+    const result = deleteLocalBranchIfOrphan(ROOT, BRANCH);
+
+    expect(result).toBe(true);
+    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(2);
+    const [, deleteArgs] = vi.mocked(spawnSync).mock.calls[1];
+    expect(deleteArgs).toContain("-D");
+    expect(deleteArgs).toContain(BRANCH);
+  });
+
+  it("returns false when local branch exists but delete fails", () => {
+    vi.mocked(spawnSync)
+      .mockReturnValueOnce(mockSpawnResult(`  ${BRANCH}\n`, 0)) // branch --list → found
+      .mockReturnValueOnce(mockSpawnResult("", 1));              // branch -D → failure
+
+    const result = deleteLocalBranchIfOrphan(ROOT, BRANCH);
+
+    expect(result).toBe(false);
+    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(2);
+  });
+
+  it("passes workspaceRoot as -C argument to both git calls", () => {
+    vi.mocked(spawnSync)
+      .mockReturnValueOnce(mockSpawnResult(`  ${BRANCH}\n`, 0))
+      .mockReturnValueOnce(mockSpawnResult("", 0));
+
+    deleteLocalBranchIfOrphan(ROOT, BRANCH);
+
+    for (const [, args] of vi.mocked(spawnSync).mock.calls) {
+      expect((args as string[])[0]).toBe("-C");
+      expect((args as string[])[1]).toBe(ROOT);
+    }
+  });
+});
+
+// ── tryReadTaskFromBranch ─────────────────────────────────────────────────────
+
+describe("tryReadTaskFromBranch", () => {
+  it("reads and parses task YAML from origin/<branch>", () => {
+    const yaml = "id: T1\nstatus: ready\nrepo: impl-repo\ndepends_on: []\nlog: []\n";
+    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnResult(yaml, 0));
+
+    const task = tryReadTaskFromBranch(ROOT, BRANCH, REL_PATH);
+
+    expect(task).not.toBeNull();
+    expect(task!.id).toBe("T1");
+    expect(task!.status).toBe("ready");
+    const [, args] = vi.mocked(spawnSync).mock.calls[0];
+    expect((args as string[]).some((a) => a.startsWith(`origin/${BRANCH}`))).toBe(true);
+  });
+
+  it("returns null when git show exits non-zero", () => {
+    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnResult("", 128));
+
+    expect(tryReadTaskFromBranch(ROOT, BRANCH, REL_PATH)).toBeNull();
+  });
+
+  it("returns null when stdout is empty", () => {
+    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnResult("", 0));
+
+    expect(tryReadTaskFromBranch(ROOT, BRANCH, REL_PATH)).toBeNull();
+  });
+
+  it("returns null when stdout is not valid YAML", () => {
+    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnResult("{invalid: yaml: here", 0));
+
+    expect(tryReadTaskFromBranch(ROOT, BRANCH, REL_PATH)).toBeNull();
+  });
+});
